import{_ as i,C as a,c as e,o,j as l,G as t,b as r,a0 as n,a as s,w as c,a1 as p}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Pensiero tattico nella boccia","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/tactics/index.md","filePath":"it/education/tactics/index.md"}');const d=i({name:"it/education/tactics/index.md"},[["render",function(i,u,d,g,m,h){const b=a("AdBanner"),f=a("Mermaid");return o(),e("div",null,[u[2]||(u[2]=l("h1",{id:"pensiero-tattico-nella-boccia",tabindex:"-1"},[s("Pensiero tattico nella boccia "),l("a",{class:"header-anchor",href:"#pensiero-tattico-nella-boccia","aria-label":'Permalink to "Pensiero tattico nella boccia"'},"​")],-1)),t(b),u[3]||(u[3]=l("p",null,"A livello d'élite, l'abilità tecnica è un requisito fondamentale. Ciò che distingue i vincitori dagli altri è l'intelligenza tattica: sapere quale tiro tentare e quando. I giocatori migliori leggono la partita con diverse mosse di anticipo e sfruttano ogni vantaggio.",-1)),u[4]||(u[4]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"Il principio fondamentale"),l("p",null,[l("strong",null,"A livello d'élite, la differenza raramente è la tecnica, ma la capacità decisionale."),s(" Vince la squadra che commette meno errori tattici.")])],-1)),u[5]||(u[5]=l("h2",{id:"quadro-decisionale-rapido",tabindex:"-1"},[s("Quadro decisionale rapido "),l("a",{class:"header-anchor",href:"#quadro-decisionale-rapido","aria-label":'Permalink to "Quadro decisionale rapido"'},"​")],-1)),(o(),r(p,null,{default:c(()=>[t(f,{id:"mermaid-16",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BIl%20tuo%20turno%5D%20--%3E%20B%7BAre%20you%20holding%3F%7D%0A%20%20%20%20B%20--%3E%7CYes%7C%20C%7BOpponent%20has%20boules%3F%7D%0A%20%20%20%20B%20--%3E%7CNo%7C%20D%7BCan%20you%20point%20closer%3F%7D%0A%0A%20%20%20%20C%20--%3E%7CYes%7C%20E%5BAspetta%20e%20pianifica%5D%0A%20%20%20%20C%20--%3E%7CNo%7C%20F%7BSafe%20to%20add%20points%3F%7D%0A%0A%20%20%20%20F%20--%3E%7CYes%7C%20G%5BAggiungi%20punti%20con%20attenzione%5D%0A%20%20%20%20F%20--%3E%7CNo%7C%20H%5BGioca%20in%20sicurezza%2Fblocca%5D%0A%0A%20%20%20%20D%20--%3E%7CYes%2C%20high%20%25%7C%20I%5BPunto%5D%0A%20%20%20%20D%20--%3E%7CForse%7C%20J%7BCan%20you%20shoot%3F%7D%0A%20%20%20%20D%20--%3E%7CNo%7C%20K%5BSpostare%20il%20cricco%20o%20il%20blocco%5D%0A%0A%20%20%20%20J%20--%3E%7CYes%2C%20%3E60%25%7C%20L%5BSparare%5D%0A%20%20%20%20J%20--%3E%7CNo%7C%20K%0A%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23fff3e0%0A%20%20%20%20style%20F%20fill%3A%23fff3e0%0A%20%20%20%20style%20J%20fill%3A%23ffebee%0A"})]),fallback:c(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[6]||(u[6]=n('<h2 id="la-mentalita-tattica" tabindex="-1">La mentalità tattica <a class="header-anchor" href="#la-mentalita-tattica" aria-label="Permalink to &quot;La mentalità tattica&quot;">​</a></h2><h3 id="pensa-in-termini-di-probabilita" tabindex="-1">Pensa in termini di probabilità <a class="header-anchor" href="#pensa-in-termini-di-probabilita" aria-label="Permalink to &quot;Pensa in termini di probabilità&quot;">​</a></h3><p>Ogni lancio ha una probabilità di successo. Una buona tattica significa scegliere lanci in cui:</p><ul><li>La probabilità di successo è abbastanza alta</li><li>La ricompensa giustifica il rischio</li><li>Il fallimento non fa troppo male</li></ul><p><strong>Esempio di decisione:</strong></p><ul><li>Tiro difficile: 40% di successo, guadagna 3 punti</li><li>Punto sicuro: 80% di successo, guadagna 1 punto</li></ul><p>Qual è la scelta migliore? Dipende dal punteggio, dalla situazione e dalla tua sicurezza.</p><h3 id="considera-tutte-le-opzioni" tabindex="-1">Considera tutte le opzioni <a class="header-anchor" href="#considera-tutte-le-opzioni" aria-label="Permalink to &quot;Considera tutte le opzioni&quot;">​</a></h3><p>Prima di ogni lancio, considera:</p><ol><li><strong>Punto:</strong> Posiziona una boccia vicino al jack</li><li><strong>Tiro:</strong> Rimuovi la boccia di un avversario</li><li><strong>Blocco:</strong> Posiziona una boccia per ostacolare</li><li><strong>Spostare il cric:</strong> Colpire intenzionalmente il cric</li><li><strong>Sacrificio:</strong> Accettare una brutta posizione da impostare in seguito</li></ol><p>Non affidarti alla scelta ovvia. Valuta le alternative.</p><h3 id="leggi-la-situazione" tabindex="-1">Leggi la situazione <a class="header-anchor" href="#leggi-la-situazione" aria-label="Permalink to &quot;Leggi la situazione&quot;">​</a></h3><p>Fattori da considerare:</p><ul><li>Punteggio attuale (chi è in vantaggio, di quanto)</li><li>Bocce rimanenti (tue e loro)</li><li>Posizione sul terreno</li><li>Tendenze opposte</li><li>I punti di forza del tuo team</li></ul><h2 id="principi-tattici-fondamentali" tabindex="-1">Principi tattici fondamentali <a class="header-anchor" href="#principi-tattici-fondamentali" aria-label="Permalink to &quot;Principi tattici fondamentali&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">I 6 principi tattici</p><ol><li><strong>Controlla il Jack</strong> - La posizione è potenza</li><li><strong>Strategia di distanza e superficie</strong> - Adattarsi alle condizioni</li><li><strong>Detta lo stile di gioco</strong> - Forza i tuoi punti di forza</li><li><strong>Gestisci il rischio rispetto alla ricompensa</strong> - Adatta il rischio alla situazione</li><li><strong>Usa le bocce con saggezza</strong> - A volte concedi 1 per evitarne 3</li><li><strong>Pensa al futuro</strong> - Visualizza le prossime 2-3 mosse</li></ol></div><h3 id="principio-1-controllare-il-jack" tabindex="-1">Principio 1: Controllare il Jack <a class="header-anchor" href="#principio-1-controllare-il-jack" aria-label="Permalink to &quot;Principio 1: Controllare il Jack&quot;">​</a></h3><p>La squadra che controlla la posizione del cricco ha un vantaggio significativo.</p><p><strong>Modi per controllare:</strong></p><ul><li>Vinci il diritto di lanciare il jack</li><li>Spostare il cric su un terreno favorevole</li><li>Proteggere il cric da eventuali spostamenti</li></ul><p><strong>Strategia di posizionamento del jack:</strong></p><ul><li>Jack corto: favorisce il tiro, è più facile colpire i bersagli a distanza ravvicinata</li><li>Jack lungo: favorisce la puntatura, il tiro diventa più difficile</li><li>Ostacoli vicini: crea sfide per gli avversari</li></ul><p><strong>Sfrutta le debolezze dell&#39;avversario:</strong></p><ul><li>Osserva la loro tecnica di puntamento: usano sempre lo stesso arco o stile?</li><li>Se non riescono ad adattarsi (ad esempio, solo rotolare, solo lanciare), posizionare il jack per forzare lanci scomodi</li><li>Posizionare il cric a distanze o posizioni che ne espongano i limiti</li><li>Sfrutta una debolezza solo se non la condividi: considera prima i punti di forza del tuo team</li></ul><h3 id="principio-2-strategia-di-distanza-e-superficie" tabindex="-1">Principio 2: Strategia di distanza e superficie <a class="header-anchor" href="#principio-2-strategia-di-distanza-e-superficie" aria-label="Permalink to &quot;Principio 2: Strategia di distanza e superficie&quot;">​</a></h3><p>L&#39;equilibrio ottimale tra puntamento e tiro dipende molto dalla distanza e dal terreno:</p><div class="info custom-block"><p class="custom-block-title">Strategia della distanza</p><p><strong>Corto (6-7 m):</strong> Favorisce il tiro: è più facile colpire a distanza ravvicinata <strong>Media (7-9 m):</strong> La superficie è ciò che conta di più</p><ul><li>Superficie liscia → spara di più</li><li>Superficie ruvida → punta di più</li></ul><p><strong>Lungo (9-11 m):</strong> Puntamento favorevole: la precisione del tiro diminuisce significativamente</p></div>',27)),(o(),r(p,null,{default:c(()=>[t(f,{id:"mermaid-264",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BDistanza%5D%20--%3E%20B%5B6-7m%20Corto%5D%0A%20%20%20%20A%20--%3E%20C%5B7-9m%20Medio%5D%0A%20%20%20%20A%20--%3E%20D%5B9-11%20m%20di%20lunghezza%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BSpara%20di%20pi%C3%B9%5D%0A%20%20%20%20C%20--%3E%20F%7BSurface%3F%7D%0A%20%20%20%20D%20--%3E%20G%5BPunta%20di%20pi%C3%B9%5D%0A%0A%3CAdInArticle%20%2F%3E%0A%0A%20%20%20%20F%20--%3E%7CSmooth%7C%20H%5BSpara%20di%20pi%C3%B9%5D%0A%20%20%20%20F%20--%3E%7CRough%7C%20I%5BPunta%20di%20pi%C3%B9%5D%0A%0A%20%20%20%20style%20E%20fill%3A%23ffcdd2%0A%20%20%20%20style%20H%20fill%3A%23ffcdd2%0A%20%20%20%20style%20I%20fill%3A%23c8e6c9%0A%20%20%20%20style%20G%20fill%3A%23c8e6c9%0A"})]),fallback:c(()=>[...u[1]||(u[1]=[s(" Loading... ",-1)])]),_:1})),u[7]||(u[7]=n('<p><strong>La tua percentuale di tiri personale:</strong></p><ul><li>Se spari con una percentuale di successo del 75%+, spara più spesso</li><li>Valutare la possibilità di tirare per ridurre i punti dell&#39;avversario (anche se non si è in vantaggio)</li><li>Tirare per ridurre il punteggio delle bocce dell&#39;avversario (da 3 a 1) è un prezioso metodo per controllare i danni</li></ul><p><strong>Sparare come strategia a lungo termine:</strong></p><ul><li>Se spari con tutte le tue bocce, considera il tuo tasso di successo cumulativo</li><li>Calcola: quando colpisci tutti i tiri, guadagni molti più punti</li><li>Anche sbagliare qualche tiro può ridurre i punti dell&#39;avversario</li><li>Esempio: Manca 1-2 colpi ma rimuovi comunque le minacce, quindi ottieni un grande guadagno quando colpisci tutti</li><li>Questo è un rischio calcolato: accetta alcune estremità perse per ottenere vittorie più grandi quando funziona</li></ul><h3 id="principio-3-dettare-lo-stile-di-gioco" tabindex="-1">Principio 3: Dettare lo stile di gioco <a class="header-anchor" href="#principio-3-dettare-lo-stile-di-gioco" aria-label="Permalink to &quot;Principio 3: Dettare lo stile di gioco&quot;">​</a></h3><p>A livello d&#39;élite, la maggior parte dei giocatori sa sia puntare che tirare bene. La chiave è forzare il gioco nello stile più forte della propria squadra.</p><p><strong>Se la tua squadra ha tiratori forti:</strong></p><ul><li>Spara il più possibile - usa il tuo vantaggio</li><li>Non sprecare la tua forza puntando quando puoi dominare sparando</li><li>Controlla il gioco rimuovendo le minacce prima che si accumulino</li><li>Il jack corto-medio mantiene efficace lo sparo</li></ul><p><strong>Contro tiratori altrettanto forti:</strong></p><ul><li>Impedisci loro di diventare bersagli facili sparando per primi</li><li>Giocare a lunga distanza per ridurre la percentuale di tiro di tutti</li><li>La squadra che tira per prima spesso controlla la fine</li></ul><p><strong>Se gli avversari ti superano nei tiri:</strong></p><ul><li>Gioca a lungo jack in modo coerente: anche i tiratori d&#39;élite calano la percentuale a 10m+</li><li>Forza una battaglia di puntamento in cui puoi competere</li><li>Fateli sparare da angoli difficili o attraverso ostacoli</li></ul><h3 id="principio-4-gestire-il-rischio-rispetto-alla-ricompensa" tabindex="-1">Principio 4: Gestire il rischio rispetto alla ricompensa <a class="header-anchor" href="#principio-4-gestire-il-rischio-rispetto-alla-ricompensa" aria-label="Permalink to &quot;Principio 4: Gestire il rischio rispetto alla ricompensa&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situazione</th><th>Tolleranza al rischio</th></tr></thead><tbody><tr><td>Avanti comodamente</td><td>Basso - proteggi il tuo vantaggio</td></tr><tr><td>Chiudi il gioco</td><td>Medio - rischi calcolati</td></tr><tr><td>Significativamente indietro</td><td>Alto - bisogna correre dei rischi</td></tr><tr><td>Fine finale</td><td>Dipende dalla differenza di punteggio</td></tr></tbody></table><h3 id="principio-5-usa-le-tue-bocce-con-saggezza" tabindex="-1">Principio 5: Usa le tue bocce con saggezza <a class="header-anchor" href="#principio-5-usa-le-tue-bocce-con-saggezza" aria-label="Permalink to &quot;Principio 5: Usa le tue bocce con saggezza&quot;">​</a></h3><p>La gestione del bocce distingue i giocatori d&#39;élite:</p><ul><li>Quando l&#39;avversario finisce le bocce, bisogna decidere attentamente: aggiungere punti o giocare sul sicuro?</li><li>Quando sei in svantaggio, calcola se puoi realisticamente riprendere il punto</li><li>A volte concedere 1 punto è meglio che sprecare bocce e concederne 3</li><li>Tieni sempre traccia delle bocce rimanenti, tue e loro.</li></ul><h3 id="principio-6-pensa-a-piu-mosse-in-anticipo" tabindex="-1">Principio 6: Pensa a più mosse in anticipo <a class="header-anchor" href="#principio-6-pensa-a-piu-mosse-in-anticipo" aria-label="Permalink to &quot;Principio 6: Pensa a più mosse in anticipo&quot;">​</a></h3><p>Pensiero d&#39;élite:</p><ul><li>Prima di lanciare, visualizza le prossime 2-3 bocce di entrambe le squadre</li><li>Qual è la risposta migliore del tuo avversario se hai successo? E se fallisci?</li><li>In che modo questo lancio prepara il tuo prossimo?</li><li>Considera lo scenario finale dalla posizione attuale</li></ul><h2 id="situazioni-tattiche-comuni" tabindex="-1">Situazioni tattiche comuni <a class="header-anchor" href="#situazioni-tattiche-comuni" aria-label="Permalink to &quot;Situazioni tattiche comuni&quot;">​</a></h2><h3 id="stai-tenendo-la-palla-e-l-39-avversario-ha-ancora-delle-bocce" tabindex="-1">Stai tenendo la palla e l&#39;avversario ha ancora delle bocce <a class="header-anchor" href="#stai-tenendo-la-palla-e-l-39-avversario-ha-ancora-delle-bocce" aria-label="Permalink to &quot;Stai tenendo la palla e l&amp;#39;avversario ha ancora delle bocce&quot;">​</a></h3><p>Devi aspettare: è il loro turno di lanciare. Usa questo tempo per:</p><ul><li>Analizza cosa è probabile che facciano</li><li>Pianifica la tua risposta ai loro possibili lanci</li><li>Rimani concentrato e pronto</li></ul><h3 id="stai-tenendo-e-l-39-avversario-e-senza-bocce" tabindex="-1">Stai tenendo e l&#39;avversario è senza bocce <a class="header-anchor" href="#stai-tenendo-e-l-39-avversario-e-senza-bocce" aria-label="Permalink to &quot;Stai tenendo e l&amp;#39;avversario è senza bocce&quot;">​</a></h3><p>Ora puoi giocare le bocce rimanenti. <strong>Opzioni:</strong></p><ul><li>Aggiungi altri punti se puoi farlo in sicurezza</li><li>Blocco per proteggere dal movimento del martinetto</li><li>Gioca in sicurezza: non rischiare di trasformare una vittoria di 2 punti in una sconfitta</li></ul><p><strong>Decisione chiave:</strong> Vale la pena rischiare di aggiungere punti aprendo potenzialmente il gioco?</p><h3 id="non-stai-trattenendo" tabindex="-1">Non stai trattenendo <a class="header-anchor" href="#non-stai-trattenendo" aria-label="Permalink to &quot;Non stai trattenendo&quot;">​</a></h3><p>Devi lanciare. <strong>Opzioni:</strong></p><ul><li>Punta più vicino della loro migliore boccia</li><li>Tirano la loro boccia migliore</li><li>Sposta il jack sulle tue bocce</li><li>Blocca per limitare il loro punteggio (se non puoi prendere il punto)</li></ul><p><strong>Fattori decisionali:</strong> La tua percentuale di tiri, il numero di bocce rimanenti (entrambe le squadre), il punteggio attuale</p><h3 id="situazioni-dell-39-ultima-boccia" tabindex="-1">Situazioni dell&#39;ultima boccia <a class="header-anchor" href="#situazioni-dell-39-ultima-boccia" aria-label="Permalink to &quot;Situazioni dell&amp;#39;ultima boccia&quot;">​</a></h3><p>Quando hai l&#39;ultima palla:</p><ul><li>Massima pressione ma anche massimo controllo</li><li>Prenditi il tuo tempo: valuta tutte le opzioni</li><li>Considera: puntare, sparare o muovere il cricco?</li><li>Eseguire con pieno impegno</li></ul><p>Quando l&#39;avversario ha l&#39;ultima boccia:</p><ul><li>Hai fatto quello che potevi: accetta il risultato</li><li>Se possibile, crea una situazione in cui non ci sia una risposta facile per loro</li><li>Più minacce sono meglio di una</li></ul><h2 id="leggere-i-tuoi-avversari" tabindex="-1">Leggere i tuoi avversari <a class="header-anchor" href="#leggere-i-tuoi-avversari" aria-label="Permalink to &quot;Leggere i tuoi avversari&quot;">​</a></h2><p>A livello d&#39;élite, lo scouting è importante. Conosci i tuoi avversari prima di giocare.</p><h3 id="intelligence-pre-partita" tabindex="-1">Intelligence pre-partita <a class="header-anchor" href="#intelligence-pre-partita" aria-label="Permalink to &quot;Intelligence pre-partita&quot;">​</a></h3><ul><li>Qual è il loro stile di gioco preferito (squadra che spara contro squadra che punta)?</li><li>Chi è il loro tiratore più forte? Il Pointer?</li><li>Quali distanze preferiscono?</li><li>Come si comportano sotto pressione nelle finali?</li></ul><h3 id="osservazione-in-partita" tabindex="-1">Osservazione in partita <a class="header-anchor" href="#osservazione-in-partita" aria-label="Permalink to &quot;Osservazione in partita&quot;">​</a></h3><ul><li>Tieni traccia dei loro tassi di successo durante la partita</li><li>Nota se qualcuno sta avendo una giornata no</li><li>Identifica chi gestisce bene la pressione e chi no</li><li>Regola il posizionamento del jack in base a ciò che osservi</li></ul><h3 id="sfrutta-cio-che-trovi" tabindex="-1">Sfrutta ciò che trovi <a class="header-anchor" href="#sfrutta-cio-che-trovi" aria-label="Permalink to &quot;Sfrutta ciò che trovi&quot;">​</a></h3><ul><li>Quando possibile, puntare ai giocatori più deboli</li><li>Costringere il loro tiratore debole a sparare, o il loro puntatore debole a puntare</li><li>Se qualcuno è in difficoltà, continua a fargli pressione</li></ul><h2 id="in-questa-sezione" tabindex="-1">In questa sezione <a class="header-anchor" href="#in-questa-sezione" aria-label="Permalink to &quot;In questa sezione&quot;">​</a></h2><ul><li><strong><a href="/it/educazione/tattiche/probabilità">Decisioni basate sulla probabilità</a></strong> - Usare la matematica per fare scelte migliori</li></ul><h2 id="riepilogo-tutte-le-regole-tattiche" tabindex="-1">Riepilogo: Tutte le regole tattiche <a class="header-anchor" href="#riepilogo-tutte-le-regole-tattiche" aria-label="Permalink to &quot;Riepilogo: Tutte le regole tattiche&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regola n. 1: la regola della probabilità</p><p><strong>Scegli i lanci in cui la probabilità di successo giustifica il rischio.</strong> Considera: tasso di successo, ricompensa in caso di successo, costo in caso di fallimento</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 2: la regola del controllo del jack</p><p><strong>La squadra che controlla la posizione del jack è avvantaggiata.</strong> Usa il posizionamento del jack per sfruttare i punti deboli dell&#39;avversario e favorire i tuoi punti di forza</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 3: la regola della distanza</p><p><strong>La distanza corta favorisce il tiro, la distanza lunga favorisce la mira.</strong> Distanza media: la qualità della superficie determina l&#39;equilibrio</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 4: la regola dello stile</p><p><strong>Imponi al gioco lo stile più forte della tua squadra.</strong> Se siete tiratori forti, tirate di più. Non sprecate il vostro vantaggio.</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 5: La regola della gestione delle bocce</p><p><strong>A volte è meglio concedere 1 punto che rischiarne 3.</strong> Sappi quando tagliare le perdite e salvare le bocce per la prossima manche</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 6: La regola del pensare in anticipo</p><p><strong>Visualizza le prossime 2-3 mosse di entrambe le squadre.</strong> Qual è la loro risposta migliore? Come si preannuncia il tuo prossimo lancio?</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 7: La regola dello scouting</p><p><strong>Conosci i tuoi avversari prima di giocare.</strong> Tieni traccia delle loro preferenze, dei tassi di successo e delle risposte alla pressione</p></div><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>A livello d&#39;élite, la differenza raramente è la tecnica, ma la capacità decisionale. Vince la squadra che commette meno errori tattici.</p></blockquote><p>Leggi il gioco. Conosci i tuoi punti di forza. Sfrutta i loro punti deboli. Agisci con sicurezza.</p>',58)),t(b)])}]]);export{u as __pageData,d as default};
